"use client";

import Link from "next/link";
import { useState, useEffect } from "react";
import { usePathname } from "next/navigation";

export default function Header() {
  const [isOpen, setIsOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const pathname = usePathname();

  useEffect(() => {
    const onScrollHeader = () => {
      const threshold = window.innerHeight * 0.65;
      setIsScrolled(window.scrollY > threshold);
    };
    window.addEventListener("scroll", onScrollHeader, { passive: true });
    onScrollHeader();
    return () => window.removeEventListener("scroll", onScrollHeader);
  }, []);

  const toggleMenu = () => setIsOpen(!isOpen);
  const closeMenu = () => setIsOpen(false);

  return (
    <header className={`site-header site-header--fixed ${isScrolled ? "is-scrolled" : ""}`}>
      <div className="container nav-inner">
        <Link className="brand" href="/" aria-label="Cosuniq home">
          <img src="/assets/logo.png" alt="Cosuniq" />
          <div className="brand-text">
            <strong>COSUNIQ</strong>
            <span>Technologies</span>
          </div>
        </Link>
        <nav className="nav-links" aria-label="Primary">
          <Link href="/" className={pathname === "/" ? "active" : ""}>Home</Link>
          <Link href="/services" className={pathname === "/services" ? "active" : ""}>What we do</Link>
          <Link href="/portfolio" className={pathname === "/portfolio" ? "active" : ""}>Work</Link>
          <Link href="/about" className={pathname === "/about" ? "active" : ""}>Studio</Link>
          <Link href="/contact" className={pathname === "/contact" ? "active" : ""}>Contact</Link>
        </nav>
        <Link className="btn btn-primary btn-sm nav-cta" href="/contact">Say hello</Link>
        <button 
          className="menu-toggle" 
          id="menu-toggle" 
          type="button" 
          aria-label="Open menu" 
          aria-expanded={isOpen} 
          aria-controls="mobile-nav"
          onClick={toggleMenu}
        >
          <span></span>
        </button>
      </div>
      <div className="container">
        <nav className={`mobile-nav ${isOpen ? "open" : ""}`} id="mobile-nav" aria-label="Mobile">
          <Link href="/" className={pathname === "/" ? "active" : ""} onClick={closeMenu}>Home</Link>
          <Link href="/services" className={pathname === "/services" ? "active" : ""} onClick={closeMenu}>What we do</Link>
          <Link href="/portfolio" className={pathname === "/portfolio" ? "active" : ""} onClick={closeMenu}>Work</Link>
          <Link href="/about" className={pathname === "/about" ? "active" : ""} onClick={closeMenu}>Studio</Link>
          <Link href="/contact" className={pathname === "/contact" ? "active" : ""} onClick={closeMenu}>Contact</Link>
        </nav>
      </div>
    </header>
  );
}
